  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Users endpoint – now uses the env‑based emails
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: demoEmails[0] },
    { id: 2, name: 'Bob',   email: demoEmails[1] },
  ]);
});

