    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

app.listen(PORT, () => console.log(`Server running on port ${PORT}`));

module.exports = app;
```

### Why this helps

* **Port flexibility** – your code now adapts to whatever the orchestrator exposes (Docker, Heroku, Kubernetes, etc.).
* **Security** – using `process.env` keeps any secret-dependent values out of the source tree.  
  (The `app.js` file has no secrets, but it keeps the pattern consistent for future growth.)
* **Logging clarity** – the logged message now reflects the real port.

---

### Quick “no‑demands” list for this repo

1. **`PORT`** – always sourced from `process.env`.  
2. **Any other build‑time configuration** (e.g., DB URLs, API keys) should live in `.env` / `.env.test` and be passed via `process.env`.  
3. **Static data for examples** (users in `/users`) can stay hard‑coded, but in production it should come from a database or another external service and be behind auth.

If your project grows (additional files, DB clients, external services), add the same pattern: extract any literal string that might change between environments into a corresponding env var in the `.env` file, and reference it via `process.env` in the code.

